changes.sections/multicolumn-features-wrap.liqui:
{% # theme-check-disable %}
<div class="multicolumn multicolumn--{{ section.settings.columns_desktop }}">
  {%- if section.settings.title != blank -%}
    <div class="multicolumn__header"><h2>{{ section.settings.title | escape }}</h2></div>
  {%- endif -%}
  <ul class="multicolumn__list">
    {%- for block in section.blocks -%}
      <li class="multicolumn__item" {{ block.shopify_attributes }}>
        {%- if block.settings.link != blank -%}<a href="{{ block.settings.link }}" class="multicolumn__link">{%- endif -%}
        {%- if block.settings.image != blank -%}
          <div class="multicolumn__media">{{ block.settings.image | image_url: width: 600 | image_tag: loading: 'lazy' }}</div>
        {%- endif -%}
        {%- if block.settings.heading != blank -%}<h3>{{ block.settings.heading | escape }}</h3>{%- endif -%}
        {%- if block.settings.text != blank -%}<div class="rte">{{ block.settings.text }}</div>{%- endif -%}
        {%- if block.settings.link != blank -%}</a>{%- endif -%}
      </li>
    {%- endfor -%}
  </ul>
  {%- if section.settings.button_label != blank and section.settings.button_link != blank -%}
    <a class="button" href="{{ section.settings.button_link }}">{{ section.settings.button_label | escape }}</a>
  {%- endif -%}
</div>

{% schema %}
{
  "name": "Multicolumn",
  "tag": "section",
  "class": "section-multicolumn",
  "max_blocks": 6,
  "settings": [
    {"type": "text", "id": "title", "label": "Heading", "default": "Why shop with us"},
    {"type": "range", "id": "columns_desktop", "label": "Columns on desktop", "min": 1, "max": 4, "step": 1, "default": 3},
    {"type": "header", "content": "Button"},
    {"type": "text", "id": "button_label", "label": "Button label"},
    {"type": "url", "id": "button_link", "label": "Button link"}
  ],
  "blocks": [
    {
      "type": "column",
      "name": "Column",
      "settings": [
        {"type": "image_picker", "id": "image", "label": "Image"},
        {"type": "text", "id": "heading", "label": "Heading", "default": "Column"},
        {"type": "richtext", "id": "text", "label": "Description", "default": "<p>Pair text with an image to focus on your chosen product.</p>"},
        {"type": "url", "id": "link", "label": "Link"}
      ]
    }
  ],
  "presets": [{"name": "Multicolumn", "blocks": [{"type": "column"}, {"type": "column"}, {"type": "column"}]}]
}
{% endschema %}
